func (r *MutationResolver) CompleteOnboarding(ctx context.Context, input gqlmodel.CompleteOnboardingInput) (*onboardingports.OnboardingState, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceOrganization, permission.OpUpdate)
	if err != nil {
		return nil, err
	}
	if authCtx.UserID.IsNil() || authCtx.IsAPIKey() || authCtx.IsAgent() {
		return nil, errortypes.NewAuthorizationError("Onboarding must be completed by a person")
	}
	if input.Organization == nil {
		return nil, errortypes.NewValidationError(
			"organization",
			errortypes.ErrRequired,
			"Organization is required",
		)
	}

	stateID, err := gqlid.ParseIDField("organization.stateId", input.Organization.StateID)
	if err != nil {
		return nil, err
	}

	tenantInfo := actorutil.TenantInfoFrom(authCtx)
	tenantInfo.UserID = authCtx.UserID

	return r.OnboardingService.Complete(ctx, &onboardingports.CompleteOnboardingRequest{
		TenantInfo: tenantInfo,
		Actor:      actorutil.FromAuthContext(authCtx),
		Organization: onboardingports.OnboardingOrganization{
			Name:         input.Organization.Name,
			Timezone:     input.Organization.Timezone,
			AddressLine1: input.Organization.AddressLine1,
			City:         input.Organization.City,
			StateID:      stateID,
			PostalCode:   input.Organization.PostalCode,
			ScacCode:     gqlscalar.StringValue(input.Organization.SCACCode),
			DOTNumber:    gqlscalar.StringValue(input.Organization.DOTNumber),
		},
		OperationType:  input.OperationType,
		LoadSampleData: input.LoadSampleData,
	})
}

func (r *QueryResolver) OnboardingState(ctx context.Context) (*onboardingports.OnboardingState, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	tenantInfo := actorutil.TenantInfoFrom(authCtx)
	tenantInfo.UserID = authCtx.UserID

	return r.OnboardingService.Get(ctx, tenantInfo)
}
